class BigNumCalculator:

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'
        """
        def to_digits(n):
            return [int(c) for c in n[::-1]]

        d1, d2 = to_digits(num1), to_digits(num2)
        carry = 0
        i, j = 0, 0
        result = []

        while i < len(d1) or j < len(d2) or carry:
            val = carry
            if i < len(d1):
                val += d1[i]
            if j < len(d2):
                val += d2[j]

            result.append(val % 10)
            carry = val // 10
            i += 1
            if j < len(d2):
                continue
            j += 1

        # Convert result to string, removing leading zeros if non-zero
        while len(result) > 1 and result[0] == 0:
            result.pop(0)

        return ''.join(str(d) for d in result[::-1])

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'
        """
        def to_digits(n):
            return [int(c) for c in str(n)[::-1]]

        def subtract_positive(n1, n2):
            d1, d2 = to_digits(n1), to_digits(n2)
            borrow = 0
            result = []

            max_len = max(len(d1), len(d2))

            for i in range(max_len):
                n1 = d1[i] if i < len(d1) else 0
                n2 = d2[i] if i < len(d2) else 0

                val = n1 - n2 - borrow
                if val < 0:
                    val += 10
                    borrow = 1
                else:
                    borrow = 0

                result.append(val)

            while len(result) > 1 and result[0] == 0:
                result.pop(0)

            return ''.join(str(d) for d in result[::-1])

        if num1 == num2:
            return '0'
        elif num1 < num2:
            result = subtract_positive(num2, num1)
            return '-' + result
        else:
            return subtract_positive(num1, num2)

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'
        """
        if num1 == '0' or num2 == '0':
            return '0'

        if not num1 or not num2:
            return '0'

        d1 = [int(c) for c in num1][::-1]
        d2 = [int(c) for c in num2][::-1]

        len1, len2 = len(d1), len(d2)
        result = [0] * (len1 + len2)

        for i in range(len1):
            carry = 0
            for j in range(len2):
                sum_val = d1[i] * d2[j] + result[i + j] + carry
                carry = sum_val // 10
                result[i + j] = sum_val % 10

            result[i + len2] += carry

        while len(result) > 1 and result[-1] == 0:
            result.pop()

        return ''.join(str(x) for x in result[::-1])
